{
  "facts": [
    {
      "topic": "scope",
      "statement": "The old fuzz entry passes two unsigned values taken from the input as parser and renderer flags, then passes the remaining bytes to md_html.",
      "evidence": [
        {
          "unit_id": "u-1056c6fa42072a012709",
          "start_line": 15,
          "end_line": 30,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The supplied recipe configures CMake with BUILD_SHARED_LIBS=OFF and links fuzz-mdhtml against libmd4c-html.a and libmd4c.a. These lines specify the recipe, not a successful build.",
      "evidence": [
        {
          "unit_id": "u-9425ff77c711ce4cae9b",
          "start_line": 21,
          "end_line": 26,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "On both source versions, md_html copies parser_flags into an MD_PARSER with ABI version zero and calls md_parse on the supplied text. The wrapper does not mask the parser flags.",
      "evidence": [
        {
          "unit_id": "u-68abec90fe8e7055cf03",
          "start_line": 533,
          "end_line": 550,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-68abec90fe8e7055cf03",
          "start_line": 573,
          "end_line": 574,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-c4f4930fda57440accaf",
          "start_line": 531,
          "end_line": 549,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-c4f4930fda57440accaf",
          "start_line": 571,
          "end_line": 572,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-1056c6fa42072a012709",
          "start_line": 18,
          "end_line": 29,
          "role": "dependency",
          "dependency_reason": "The fuzz entry supplies the parser flags and text consumed by md_html."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "trigger",
      "statement": "The after parser recognizes a table underline only when MD_FLAG_TABLES is set, a text line precedes it, and the underline passes md_is_table_underline. That helper accepts pipe separated hyphen underlines such as -|-.",
      "evidence": [
        {
          "unit_id": "u-f4008c5f64fc6cb6d4d1",
          "start_line": 6215,
          "end_line": 6228,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-f4008c5f64fc6cb6d4d1",
          "start_line": 5332,
          "end_line": 5389,
          "role": "dependency",
          "dependency_reason": "This helper defines which underline syntax satisfies the table gate."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "With MD_FLAG_SPOILERS set, the after mark collector consumes adjacent pipes as one two character potential spoiler mark before its single pipe handler.",
      "evidence": [
        {
          "unit_id": "u-e3390cb39a4acb4ce516",
          "start_line": 3284,
          "end_line": 3300,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-d10449ef4533980fa761",
          "start_line": 2755,
          "end_line": 2757,
          "role": "dependency",
          "dependency_reason": "The mark character map makes pipes eligible for collection when spoiler parsing is enabled."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "In the after table pass, only unresolved one character pipe marks become cell boundaries. Table row processing uses those boundaries to form cells, then processes each cell through the normal inline path.",
      "evidence": [
        {
          "unit_id": "u-9854f259ba7c0191d3ec",
          "start_line": 4144,
          "end_line": 4154,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-f4008c5f64fc6cb6d4d1",
          "start_line": 4610,
          "end_line": 4639,
          "role": "dependency",
          "dependency_reason": "The table row caller turns the selected marks into cell ranges."
        },
        {
          "unit_id": "u-f4008c5f64fc6cb6d4d1",
          "start_line": 4577,
          "end_line": 4595,
          "role": "dependency",
          "dependency_reason": "Each resulting cell invokes normal block content processing."
        },
        {
          "unit_id": "u-f4008c5f64fc6cb6d4d1",
          "start_line": 4736,
          "end_line": 4743,
          "role": "dependency",
          "dependency_reason": "Normal block content processing analyzes and renders inlines again."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "On that cell inline pass, unresolved two character pipe marks are paired as spoiler delimiters; resolved pairs enter and leave MD_SPAN_SPOILER, which the HTML callbacks render as x-spoiler tags.",
      "evidence": [
        {
          "unit_id": "u-fbbe6bfc649369919054",
          "start_line": 4170,
          "end_line": 4181,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-3e73bbc2708be8760b6c",
          "start_line": 3854,
          "end_line": 3869,
          "role": "dependency",
          "dependency_reason": "md_analyze_pipe pairs potential opener and closer marks."
        },
        {
          "unit_id": "u-2106c93931de3a887955",
          "start_line": 4346,
          "end_line": 4353,
          "role": "dependency",
          "dependency_reason": "The inline renderer emits spoiler span callbacks for resolved two character pipe marks."
        },
        {
          "unit_id": "u-7bb4879720e3cda5d58e",
          "start_line": 469,
          "end_line": 469,
          "role": "dependency",
          "dependency_reason": "The HTML enter callback renders the opening spoiler tag."
        },
        {
          "unit_id": "u-7223c2ad4e66a0b5f590",
          "start_line": 496,
          "end_line": 496,
          "role": "dependency",
          "dependency_reason": "The HTML leave callback renders the closing spoiler tag."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "The existing entry provides a direct route for the frozen condition: an unsigned parser flag value containing MD_FLAG_TABLES and MD_FLAG_SPOILERS, followed by Markdown shaped as a table with a cell containing ||x|| and a separate single pipe boundary. The wrapper forwards those flags; the table pass selects the single pipe and the cell pass can resolve the double pipes.",
      "evidence": [
        {
          "unit_id": "u-1056c6fa42072a012709",
          "start_line": 20,
          "end_line": 29,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-68abec90fe8e7055cf03",
          "start_line": 541,
          "end_line": 573,
          "role": "dependency",
          "dependency_reason": "md_html forwards the selected parser flags into md_parse."
        },
        {
          "unit_id": "u-e3390cb39a4acb4ce516",
          "start_line": 3284,
          "end_line": 3300,
          "role": "dependency",
          "dependency_reason": "The collector distinguishes double pipe spoiler marks from single pipe marks."
        },
        {
          "unit_id": "u-9854f259ba7c0191d3ec",
          "start_line": 4144,
          "end_line": 4154,
          "role": "dependency",
          "dependency_reason": "The table pass selects only single pipe boundaries."
        },
        {
          "unit_id": "u-f4008c5f64fc6cb6d4d1",
          "start_line": 4577,
          "end_line": 4595,
          "role": "dependency",
          "dependency_reason": "The selected cell range is processed through the normal inline path."
        },
        {
          "unit_id": "u-fbbe6bfc649369919054",
          "start_line": 4173,
          "end_line": 4180,
          "role": "dependency",
          "dependency_reason": "The normal inline path resolves two character pipe marks when spoilers are enabled."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "The before collector's table branch creates one character marks for pipes, and its table pass analyzes pipe marks as cell boundaries. These before source paths do not show preservation of a two character spoiler mark.",
      "evidence": [
        {
          "unit_id": "u-30b129775bff03a2ab73",
          "start_line": 3282,
          "end_line": 3287,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-0089077c1df368b2cb0e",
          "start_line": 4114,
          "end_line": 4119,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "In the complete old harness, process_output discards rendered output, and LLVMFuzzerTestOneInput does not inspect md_html's return value or assert an output property. Thus the supplied harness contains no existing output check for this tuple.",
      "evidence": [
        {
          "unit_id": "u-1056c6fa42072a012709",
          "start_line": 1,
          "end_line": 31,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": true,
      "audited_unit_ids": [
        "u-1056c6fa42072a012709"
      ]
    }
  ],
